#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub date: String,
    pub account: String,
    pub amount: i64,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    WrongFieldCount,
    BadDate,
    BadAmount,
}

fn valid_date(date: &str) -> bool {
    let bytes = date.as_bytes();
    bytes.len() == 10
        && bytes[4] == b'-'
        && bytes[7] == b'-'
        && bytes
            .iter()
            .enumerate()
            .all(|(index, byte)| index == 4 || index == 7 || byte.is_ascii_digit())
}

pub fn parse_line(line: &str) -> Result<Entry, ParseError> {
    let fields: Vec<&str> = line.split_whitespace().collect();
    if fields.len() != 3 {
        return Err(ParseError::WrongFieldCount);
    }
    if !valid_date(fields[0]) {
        return Err(ParseError::BadDate);
    }
    let amount = fields[2].parse().map_err(|_| ParseError::BadAmount)?;
    Ok(Entry {
        date: fields[0].to_string(),
        account: fields[1].to_string(),
        amount,
    })
}

pub fn parse_all(text: &str) -> Result<Vec<Entry>, ParseError> {
    let mut entries = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        entries.push(parse_line(line)?);
    }
    Ok(entries)
}

