use crate::entry::Entry;
use std::collections::BTreeMap;

pub fn balances(entries: &[Entry]) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        *totals.entry(entry.account.clone()).or_insert(0) += entry.amount;
    }
    totals.retain(|_, amount| *amount != 0);
    totals
}

pub fn render(entries: &[Entry]) -> String {
    let mut out = String::new();
    for (account, amount) in balances(entries) {
        out.push_str(&format!("{account}: {amount}\n"));
    }
    out
}

