pub fn windows(values: &[i32], size: usize) -> Vec<Vec<i32>> {
    if values.is_empty() || size == 0 || size > values.len() {
        return Vec::new();
    }
    let mut out = Vec::new();
    for start in 0..(values.len() - size) {
        out.push(values[start..start + size].to_vec());
    }
    out
}

