#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Idle,
    Running,
    Paused,
    Done,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Event {
    Start,
    Pause,
    Finish,
    Cancel,
}

pub fn next(state: State, event: Event) -> Option<State> {
    match (state, event) {
        (State::Idle, Event::Start) => Some(State::Running),
        (State::Running, Event::Pause) => Some(State::Paused),
        (State::Running, Event::Finish) => Some(State::Done),
        (State::Paused, Event::Start) => Some(State::Running),
        (State::Paused, Event::Cancel) => Some(State::Done),
        _ => None,
    }
}

