#[derive(Debug, PartialEq, Eq)]
pub enum IdError {
    Empty,
    NotNumeric,
    TooLarge,
}

pub fn parse_id(text: &str) -> Result<u32, IdError> {
    if text.is_empty() {
        return Err(IdError::Empty);
    }
    if !text.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err(IdError::NotNumeric);
    }
    let value: u32 = text.parse().map_err(|_| IdError::NotNumeric)?;
    if value > 9999 {
        Err(IdError::NotNumeric)
    } else {
        Ok(value)
    }
}

